INSERT INTO image (id, name, link, topic_name, description, image_category, type, link_to_post, is_delete, year) VALUES (154, 'CHO THUÊ NHÂN CÔNG BỐC XẾP HÀNG HÓA TẠI PHÚ QUỐC', 'https://conruabien.vn/wp-content/uploads/desktop/Cho-thue-nhan-cong-boc-xep-hang-hoa-tai-Phu-Quoc.jpg', null, 'Nhận bốc xếp hàng hóa theo yêu cầu Quý khách hàng [bốc xếp từ xe tải xuống đất, nhận rút container, đưa hàng hóa các loại lên lầu hoặc vô tận nhà theo yêu cầu]', null, 'desktop', 'https://conruabien.vn/dich-vu-mo-rong/boc-xep-hang-hoa', 0, null);
INSERT INTO image (id, name, link, topic_name, description, image_category, type, link_to_post, is_delete, year) VALUES (155, 'CHO THUÊ XE CẨU TẠI PHÚ QUỐC', 'https://conruabien.vn/wp-content/uploads/desktop/Cho-thue-xe-cau-tai-Phu-quoc.jpg', null, 'Cho thuê xe cẩu tại Phú Quốc với nhiều chủng loại khác nhau [cẩu hàng lên xuống xe tải, nhận rút container, cho thuê ca hoặc theo tháng, di chuyển hàng hóa theo yêu cầu]', null, 'desktop', 'https://conruabien.vn/dich-vu-chinh/dich-vu-cho-thue-xe-cau', 0, null);
INSERT INTO image (id, name, link, topic_name, description, image_category, type, link_to_post, is_delete, year) VALUES (156, 'CHO THUÊ XE ĐẦU KÉO CONTAINER ĐI PHÚ QUỐC', 'https://conruabien.vn/wp-content/uploads/desktop/Cho-thue-xe-dau-keo-Container-di-Phu-Quoc.jpg', null, 'Cho thuê đầu kéo container nhập khẩu đi Phú Quốc hoặc đi Bắc Nam với nhiều loại container: 20f 40f, container thùng mui bạc, container thùng kín ... theo yêu cầu.', null, 'desktop', 'https://conruabien.vn/dich-vu-chinh/cho-thue-xe-dau-keo-xe-container', 0, null);
INSERT INTO image (id, name, link, topic_name, description, image_category, type, link_to_post, is_delete, year) VALUES (157, 'CHÀNH XE ĐI PHÚ QUỐC', 'https://conruabien.vn/wp-content/uploads/desktop/Chanh-xe-di-Phu-quoc.jpg', null, 'Con Rùa Biển là nhà xe chuyên tuyến nhận chở các loại hàng hóa đi Phú Quốc với nhiều loại dịch vụ: bao xe, đi ghép hàng nhỏ lẻ với đa dạng phương thức vận tải khác nhau [đường bộ, đường biển, đường hàng không]', null, 'desktop', 'https://conruabien.vn/dich-vu-chinh/chanh-xe-di-phu-quoc', 0, null);
INSERT INTO image (id, name, link, topic_name, description, image_category, type, link_to_post, is_delete, year) VALUES (158, 'CHO THUÊ KHO BÃI CHỨA HÀNG HÓA MIỄN PHÍ', 'https://conruabien.vn/wp-content/uploads/desktop/Cho-thue-kho-bai-chua-hang-hoa-mien-phi-tai-Bai-xe.jpg', null, 'Quý khách hàng sử dụng dịch vụ vận chuyển hàng hóa ở bất kỳ nơi đâu của hệ thống Con Rùa Biển điều sẽ được lưu kho miễn phí ngắn hạn.', null, 'desktop', 'https://conruabien.vn/dich-vu-mo-rong/cho-thue-kho-bai', 0, null);
INSERT INTO image (id, name, link, topic_name, description, image_category, type, link_to_post, is_delete, year) VALUES (159, 'CHO THUÊ XÀ LAN CHỞ HÀNG HÓA', 'https://conruabien.vn/wp-content/uploads/desktop/Cho-thue-xa-lan-cho-hang-hoa.jpg', null, 'Con Rùa Biển cung cấp dịch vụ vận tải hàng hóa đường thủy bằng xà lan để tiết kiệm chi phí cho Khách hàng khi vận chuyển số lượng lớn hoặc hàng dự án.', null, 'desktop', 'https://conruabien.vn/dich-vu-mo-rong/cho-thue-sa-lan-phu-quoc', 0, null);
