INSERT INTO image (id, name, link, topic_name, description, image_category, is_delete, type, link_to_post, year) VALUES (11235,'Chành xe đi Nha Trang (1)','https://conruabien.vn/wp-content/uploads/2024/Chành-xe-đi-Nha-Trang-(1).jpg','Tin Tức','(Ảnh: Chành xe đi Nha Trang hằng ngày có lịch xe chạy cố định, xe chạy liên tục, chuyên nhận hàng nhỏ lẻ đi ghép xe, nhận hàng bao xe đi thẳng ra Nha Trang giao tận nơi theo yêu cầu; trong ảnh là mặt hàng nội thất đang được xếp lên xe tải để đi Nha Trang từ Sài Gòn)','hàng ghép nội thất nước sơn',0,NULL,NULL, 2024);
